package org.torproject.vpn.ui.approuting.data

import android.Manifest.permission.INTERNET
import android.content.Context
import android.content.Intent
import android.content.pm.ApplicationInfo
import android.content.pm.PackageInfo
import android.content.pm.PackageManager
import android.content.pm.ResolveInfo
import android.content.pm.Signature
import android.os.Build
import android.util.Log
import androidx.core.net.toUri
import androidx.paging.PagingSource
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.launch
import org.torproject.onionmasq.OnionMasq
import org.torproject.vpn.database.AppDatabase
import org.torproject.vpn.database.app.App
import org.torproject.vpn.database.app.Category
import org.torproject.vpn.utils.PreferenceHelper

class AppManager(private val context: Context) {

    val preferenceHelper: PreferenceHelper = PreferenceHelper(context)
    val packageManager: PackageManager = context.packageManager

    val pagedTorApps get() = appDao.pagedTorApps()
    val pagedNonTorApps get() = appDao.pagedNonTorApps()
    val categoryCount get() = appDao.categoryCount()

    val protectedApps get() = appDao.protectedApps()
    val globalRouting get() = appDao.globalRouting()

    private val browserPackages = getInstalledBrowserPackages()
    private val appDao = AppDatabase
        .getDatabase(context)
        .appDao()

    private val TAG = AppManager::class.java.simpleName

    fun getApp(packageName: String): Flow<App> {
        return appDao.getApp(packageName)
    }

    fun search(query: String): PagingSource<Int, App> {
        return appDao.search(query)
    }

    /**
     * Returns an array of tor powered apps uid installed on the device
     */
    fun getInstalledTorPoweredAppsUid(): LongArray {
        return TOR_POWERED_APP_PACKAGE_NAMES.filter { (packageName, _) ->
            try {
                isValidTorPoweredApp(packageName)
            } catch (_: PackageManager.NameNotFoundException) {
                // package not found, ignore
                false
            }
        }.mapNotNull { (packageName, _) ->
            packageManager.getApplicationInfo(packageName, 0).uid.toLong()
        }.toLongArray()
    }

    suspend fun protectAllApps(enabled: Boolean) {
        appDao.updateGlobalRouting(enabled)
    }

    suspend fun protectApp(enable: Boolean, packageName: String) {
        appDao.updateRouting(packageName, enable)
    }

    fun updateAppDatabase(packageName: String, isInstalled: Boolean) {
        CoroutineScope(Dispatchers.IO).launch {
            if (isValidTorPoweredApp(packageName)) {
                OnionMasq.setExcludedUids(getInstalledTorPoweredAppsUid())
            }

            if (isInstalled) {
                val flags = PackageManager.GET_PERMISSIONS
                try {
                    val packageInfo = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                        packageManager.getPackageInfo(
                            packageName,
                            PackageManager.PackageInfoFlags.of(flags.toLong())
                        )
                    } else {
                        packageManager.getPackageInfo(packageName, flags)
                    }
                    mapToApp(packageInfo)?.let { app -> appDao.insert(listOf(app)) }
                } catch (e: PackageManager.NameNotFoundException) {
                    Log.w(TAG, "Package not found: $packageName", e)
                }
            } else {
                appDao.delete(packageName)
            }
        }
    }

    /**
     * Updates the internal database with the installed applications
     */
    suspend fun updateAppDatabase() {
        val flags = PackageManager.GET_PERMISSIONS
        val packages = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            packageManager.getInstalledPackages(
                PackageManager.PackageInfoFlags.of(flags.toLong())
            )
        } else {
            packageManager.getInstalledPackages(flags)
        }

        val apps = packages.mapNotNull { packageInfo -> mapToApp(packageInfo) }
        val existingPackages = appDao.packages().toSet()
        val packagesToDelete = existingPackages - apps.map { it.packageName }.toSet()

        appDao.chunkedDelete(packagesToDelete)
        appDao.insert(apps)

        if (preferenceHelper.shouldMigrateProtectedApps) {
            migrateProtectedAppsToDatabase()
            preferenceHelper.shouldMigrateProtectedApps = false
        }
    }

    /**
     * Checks whether a given package is a valid Tor powered app by comparing signatures
     */
    private fun isValidTorPoweredApp(packageName: String): Boolean {
        if (!TOR_POWERED_APP_PACKAGE_NAMES.contains(packageName)) {
            return false
        }

        try {
            val packageInfo = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                packageManager.getPackageInfo(packageName, PackageManager.GET_SIGNING_CERTIFICATES)
            } else {
                @Suppress("DEPRECATION")
                packageManager.getPackageInfo(packageName, PackageManager.GET_SIGNATURES)
            }

            val signatures = when {
                Build.VERSION.SDK_INT < Build.VERSION_CODES.P -> {
                    @Suppress("DEPRECATION")
                    packageInfo.signatures
                }

                packageInfo.signingInfo?.hasMultipleSigners() == true -> {
                    packageInfo.signingInfo?.apkContentsSigners
                }

                else -> packageInfo.signingInfo?.signingCertificateHistory
            } ?: emptyArray<Signature>()

            signatures.forEach { signature ->
                val signatureString = signature.toByteArray().joinToString(separator = "") { byte ->
                    String.format("%02X", byte)
                }

                return TOR_POWERED_APP_PACKAGE_NAMES[packageName]?.contains(signatureString) == true
            }
        } catch (_: PackageManager.NameNotFoundException) {
            return false
        } catch (exception: Exception) {
            Log.e(TAG, "Error verifying app signature", exception)
            return false
        }

        Log.e(TAG, "The signature for $packageName does not match the expected signature!")
        return false
    }

    private fun isSystemApp(packageInfo: PackageInfo): Boolean {
        val flags = packageInfo.applicationInfo?.flags ?: return false
        return (flags and ApplicationInfo.FLAG_SYSTEM) != 0 ||
            (flags and ApplicationInfo.FLAG_UPDATED_SYSTEM_APP) != 0
    }

    private fun getInstalledBrowserPackages(): List<String> {
        val queryBrowsersIntent = Intent()
            .setAction(Intent.ACTION_VIEW)
            .addCategory(Intent.CATEGORY_BROWSABLE)
            .setData("https://".toUri())

        val installedBrowsers = mutableListOf<ResolveInfo>()
        installedBrowsers.addAll(
            packageManager.queryIntentActivities(
                queryBrowsersIntent,
                PackageManager.MATCH_ALL
            )
        )

        val browserPackageNames = mutableListOf<String>()
        for (browser in installedBrowsers) {
            browserPackageNames.add(browser.activityInfo.packageName)
        }
        return browserPackageNames
    }

    private fun mapToApp(packageInfo: PackageInfo): App? {
        if (packageInfo.requestedPermissions?.contains(INTERNET) != true) return null
        val applicationInfo = packageInfo.applicationInfo ?: return null
        return App(
            packageName = packageInfo.packageName,
            name = applicationInfo.loadLabel(packageManager).toString(),
            uid = applicationInfo.uid,
            category = when {
                isValidTorPoweredApp(packageInfo.packageName) -> Category.TOR
                browserPackages.contains(packageInfo.packageName) -> Category.BROWSER
                isSystemApp(packageInfo) -> Category.SYSTEM
                else -> Category.OTHER
            },
            isRoutingEnabled = true
        )
    }

    private suspend fun migrateProtectedAppsToDatabase() {
        if (preferenceHelper.protectAllApps) {
            Log.d(TAG, "All apps are protected, nothing to migrate")
            return
        }

        val protectedApps = preferenceHelper.protectedApps
        if (protectedApps.isEmpty()) {
            Log.i(TAG, "Migrating protected apps, none are protected")
            appDao.updateGlobalRouting(false)
        } else {
            Log.i(TAG, "Migrating protected apps, specific are protected")
            appDao.updateRouting(appDao.packages() - protectedApps, false)
        }

        Log.i(TAG, "Finished migrating protected apps")
    }

    companion object {
        private val TOR_POWERED_APP_PACKAGE_NAMES: Map<String, List<String>> = hashMapOf(
            // cwtch
            Pair(
                "im.cwtch.flwtch",
                listOf(
                    "",
                    ""
                )
            ),
            // briar
            Pair(
                "org.briarproject.briar.android",
                listOf(
                    ""
                )
            ),
            Pair(
                "org.briarproject.mailbox",
                listOf(
                    ""
                )
            ),
            // onionshare
            Pair(
                "org.onionshare.android",
                listOf(
                    ""
                )
            ),
            Pair(
                "org.onionshare.android.fdroid",
                listOf(
                    ""
                )
            ),
            // orbot
            Pair(
                "org.torproject.android",
                listOf(
                    ""
                )
            ),
            // tor-browser
            Pair(
                "org.torproject.torbrowser",
                listOf(
                    ""
                )
            ),
            Pair(
                "org.torproject.torbrowser_alpha",
                listOf(
                    ""
                )
            ),
            // tor services
            Pair(
                "org.torproject.torservices",
                listOf(
                    ""
                )
            )
        )
    }
}
